# owner: platform
"""Absence notices that go home to parents."""

from datetime import date
from typing import Iterable, List

from rosterkit.attendance import days_missed
from rosterkit.models import Mark, Student


def _own_marks(
    student: Student, marks: Iterable[Mark]
) -> List[Mark]:
    found = list(marks)
    for mark in found:
        if mark.student_id != student.student_id:
            raise ValueError("mark for another student")
    return found


def _absent_days(
    student: Student, marks: Iterable[Mark]
) -> List[date]:
    missed = days_missed(_own_marks(student, marks))
    if not missed:
        raise ValueError("no absences to report")
    return missed


def _day_list(missed: List[date]) -> str:
    noun = "day" if len(missed) == 1 else "days"
    listed = ", ".join(item.isoformat() for item in missed)
    return f"{len(missed)} {noun}: {listed}"


def absence_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    """One sentence for a parent naming the absent days."""
    missed = _absent_days(student, marks)
    name = f"{student.first_name} {student.last_name}"
    return f"{name} was absent on {_day_list(missed)}."

