# owner: platform
import unittest
from datetime import date

from rosterkit.models import Mark, Student
from rosterkit.notices import absence_notice

student = Student("1003", "Lovelace", "Ada", "A")


def mark(number, status, student_id="1003"):
    return Mark(student_id, date(2026, 9, number), status)


class AbsenceNoticeTests(unittest.TestCase):
    def test_lists_absent_days_oldest_first(self):
        marks = [mark(5, "absent"), mark(3, "present")]
        marks.append(mark(1, "absent"))
        self.assertEqual(
            absence_notice(student, marks),
            "Ada Lovelace was absent on 2 days: "
            "2026-09-01, 2026-09-05."
        )

    def test_single_day_is_singular(self):
        marks = [mark(3, "absent")]
        self.assertEqual(
            absence_notice(student, marks),
            "Ada Lovelace was absent on 1 day: 2026-09-03."
        )

    def test_excused_days_are_left_out(self):
        marks = [mark(1, "absent"), mark(3, "excused")]
        self.assertEqual(
            absence_notice(student, marks),
            "Ada Lovelace was absent on 1 day: 2026-09-01."
        )

    def test_other_students_marks_raise(self):
        marks = [mark(1, "absent"), mark(3, "late", "1002")]
        with self.assertRaises(ValueError):
            absence_notice(student, marks)

    def test_no_absences_raises(self):
        marks = [mark(1, "present"), mark(3, "late")]
        with self.assertRaises(ValueError):
            absence_notice(student, marks)

    def test_no_marks_raises(self):
        with self.assertRaises(ValueError):
            absence_notice(student, [])
